const BW_bps = 100e6;      // 100 Mbps link
const RTT_s  = 0.100;       // 100 ms round trip
const MSS    = 1460;        // bytes per segment

// Bandwidth-delay product: bytes that fit 'in flight' on this path.
const BDP = (BW_bps / 8) * RTT_s;          // bytes
const targetSegs = Math.ceil(BDP / MSS);

// Slow start: cwnd starts at IW=10 MSS and doubles each RTT.
let cwnd = 10;             // in MSS
let rtts = 0;
while (cwnd < targetSegs) { cwnd *= 2; rtts++; }

console.log('BDP bytes:', BDP);
console.log('target segments:', targetSegs);
console.log('RTTs to fill (from IW=10):', rtts);
